import axios from 'axios';
import { Frost, ThresholdBls } from '../packages/ztan-crypto/src';

const API_URL = 'http://localhost:3010/api/v1/ztan';

async function runVerify() {
    console.log('🚀 Starting MPC E2E Verification (RFC-001 v1.5)');

    // 0. RESET
    await axios.post(`${API_URL}/ceremony/reset`);
    console.log('✔ State reset.');

    // 1. INIT
    const messageHash = '7289f43e1d3e4b5a6c7d8e9f0a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f8a9b';
    const participants = ['Node-A', 'Node-B', 'Node-C'];
    const threshold = 2;

    const initResp = await axios.post(`${API_URL}/ceremony/init`, {
        threshold,
        participants,
        messageHash
    });
    console.log('✔ Ceremony Initialized. Status:', initResp.data.status);

    // 2. ROUND 1: Commitments
    console.log('--- ROUND 1: VSS Commitments ---');
    const dkgData: any = {};
    for (const nodeId of participants) {
        const dkg = Frost.generateRound1(threshold, participants.length);
        dkgData[nodeId] = dkg;
        const resp = await axios.post(`${API_URL}/ceremony/commitments`, {
            nodeId,
            commitments: dkg.commitments
        });
        console.log(`  ✔ ${nodeId} submitted commitments. Status: ${resp.data.status}`);
    }

    // 3. ROUND 2: Share Exchange
    console.log('--- ROUND 2: Secret Shares ---');
    for (const senderNodeId of participants) {
        const shares: Record<string, string> = {};
        const senderDkg = dkgData[senderNodeId];

        participants.forEach((targetNodeId, idx) => {
            // idx + 1 because evaluatePolynomial is 1-indexed for x
            const share = Frost.evaluatePolynomial(senderDkg.coefficients, idx + 1);
            shares[targetNodeId] = share;
        });

        const resp = await axios.post(`${API_URL}/ceremony/shares`, {
            nodeId: senderNodeId,
            shares
        });
        console.log(`  ✔ ${senderNodeId} distributed shares. Status: ${resp.data.status}`);
    }

    // 4. SIGNING
    console.log('--- SIGNING: Partial Signatures ---');
    const finalState = (await axios.get(`${API_URL}/ceremony/active`)).data.active;
    const masterPk = finalState.masterPublicKey;
    console.log('✔ Master Public Key Derived:', masterPk);

    // Nodes A and B will sign
    for (const nodeId of ['Node-A', 'Node-B']) {
        // Fetch shares sent to this node
        const sharesResp = await axios.get(`${API_URL}/ceremony/shares/${nodeId}`);
        const myShares = Object.values(sharesResp.data.shares) as string[];

        // Compute local secret share
        const mySecretShare = Frost.aggregateShares(myShares);

        // Generate partial signature (v1.5 Context Bound)
        const partialSig = await ThresholdBls.signShare(
            messageHash, 
            mySecretShare, 
            finalState.ceremonyId,
            threshold,
            participants,
            participants.indexOf(nodeId) + 1
        );

        const resp = await axios.post(`${API_URL}/ceremony/sign`, {
            nodeId,
            signature: partialSig,
            ceremonyId: finalState.ceremonyId
        });
        console.log(`  ✔ ${nodeId} signed. Status: ${resp.data.status}`);
    }

    // 5. FINAL VERIFICATION
    const completedState = (await axios.get(`${API_URL}/ceremony/active`)).data.active;
    if (completedState.status === 'COMPLETED') {
        console.log('✅ MPC CEREMONY SUCCESSFUL!');
        console.log('   Aggregated Signature:', completedState.aggregatedSignature);

        // Verify locally to be sure
        const isValid = await ThresholdBls.verify(
            completedState.aggregatedSignature,
            messageHash,
            completedState.participants.filter((p: any) => p.status === 'SIGNED').map((p: any) => p.publicKey),
            completedState.ceremonyId,
            threshold,
            participants
        );
        console.log('   Local Verification of Aggregated Signature:', isValid ? 'PASS' : 'FAIL');
    } else {
        console.log('❌ MPC CEREMONY FAILED. Final Status:', completedState.status);
    }
}

runVerify().catch(console.error);

import { Router } from 'express';
import type { Request, Response } from 'express';
import { logger } from '@packages/observability';
import { sreEngine } from '../services/sre-engine.js';
import { injectDbOutage, clearDbOutage } from '@packages/db';
import { injectRedisOutage, clearRedisOutage } from '@packages/utils';

export const debugRouter = Router();

/**
 * Simulates a latency spike in the system.
 */
debugRouter.get('/latency', (req: Request, res: Response) => {
  try {
    const delay = parseInt(req.query.delay as string) || 500;
    logger.warn({ delay }, '[DEBUG] Injecting artificial latency spike');
    
    if (!sreEngine) throw new Error('SRE Engine not initialized');
    sreEngine.reportNodeAnomaly('api-service', 0.85); 
    
    res.json({ status: 'INJECTED', type: 'LATENCY', delay });
  } catch (err: any) {
    logger.error({ error: err.message }, '[DEBUG ERROR] Latency injection failed');
    res.status(200).json({ status: 'FAILED_SAFE', error: err.message });
  }
});

/**
 * Simulates telemetry data loss.
 */
debugRouter.get('/drop-telemetry', (_req: Request, res: Response) => {
  try {
    logger.warn('[DEBUG] Simulating telemetry data loss');
    
    if (!sreEngine) throw new Error('SRE Engine not initialized');
    (sreEngine as any).injectChaos('TELEMETRY_LOSS', 'global');
    
    res.json({ status: 'INJECTED', type: 'TELEMETRY_LOSS' });
  } catch (err: any) {
    logger.error({ error: err.message }, '[DEBUG ERROR] Telemetry loss injection failed');
    res.status(200).json({ status: 'FAILED_SAFE', error: err.message });
  }
});

/**
 * Simulates a regional failover scenario.
 */
debugRouter.get('/failover', (req: Request, res: Response) => {
  try {
    const source = req.query.source as string || 'us-east-1';
    logger.warn({ source }, '[DEBUG] Simulating REGIONAL FAILOVER');
    
    if (!sreEngine) throw new Error('SRE Engine not initialized');
    sreEngine.reportNodeAnomaly('global-gateway', 1.0);
    (sreEngine as any).injectChaos('REGIONAL_FAILOVER', source);
    
    res.json({ status: 'TRIGGERED', type: 'FAILOVER', source });
  } catch (err: any) {
    logger.error({ error: err.message }, '[DEBUG ERROR] Failover trigger failed');
    res.status(200).json({ status: 'FAILED_SAFE', error: err.message });
  }
});

/**
 * Tests the integrity of the Operational Watchdog.
 */
debugRouter.get('/watchdog-test', (req: Request, res: Response) => {
  try {
    const mode = req.query.mode as string || 'FALSE_POSITIVE';
    logger.warn({ mode }, '[DEBUG] Running Watchdog Integrity Test');
    
    if (!sreEngine) throw new Error('SRE Engine not initialized');
  
    if (mode === 'FALSE_POSITIVE') {
      sreEngine.reportNodeAnomaly('api-service', 0.1); // Nominal score
    } else {
      (sreEngine as any).injectChaos('STABILITY_DRIFT', 'critical');
    }
    
    res.json({ status: 'TRIGGERED', mode });
  } catch (err: any) {
    logger.error({ error: err.message }, '[DEBUG ERROR] Watchdog test failed');
    res.status(200).json({ status: 'FAILED_SAFE', error: err.message });
  }
});

/**
 * Generic chaos injection endpoint.
 */
debugRouter.get('/chaos', (req: Request, res: Response) => {
  try {
    const { type, nodeId, score } = req.query;
    logger.warn({ type, nodeId, score }, '[DEBUG] Injecting generic chaos');
    
    if (!sreEngine) throw new Error('SRE Engine not initialized');

    if (type === 'NODE_ANOMALY' && nodeId) {
      sreEngine.reportNodeAnomaly(nodeId as string, parseFloat(score as string) || 0.8);
    } else {
      (sreEngine as any).injectChaos(type as string, nodeId as string || 'global');
    }
    
    res.json({ status: 'TRIGGERED', type, nodeId });
  } catch (err: any) {
    logger.error({ error: err.message }, '[DEBUG ERROR] Chaos injection failed');
    res.status(200).json({ status: 'FAILED_SAFE', error: err.message });
  }
});

/**
 * Resets the SRE Control Plane state for a clean certification run.
 */
debugRouter.post('/reset', (_req: Request, res: Response) => {
  try {
    if (!sreEngine) throw new Error('SRE Engine not initialized');
    
    // Multi-Layer Reset for Certification Purity
    sreEngine.reset();
    
    import('../services/operational-control/audit-engine.js').then(({ operationalAudit }) => operationalAudit.reset());
    import('../services/operational-control/policy-optimizer.js').then(({ policyOptimizer }) => policyOptimizer.reset());
    import('@packages/business').then(({ roiPipeline }) => roiPipeline.reset());
    import('../services/telemetry-simulator.js').then(({ telemetrySimulator }) => {
        // Stop any active healing
        (telemetrySimulator as any).isHealing = false;
    });

    logger.info('[DEBUG] Comprehensive system reset performed');
    res.json({ status: 'RESET_COMPLETE' });
  } catch (err: any) {
    res.status(500).json({ status: 'ERROR', error: err.message });
  }
});

/**
 * Injects simulated database or Redis failures.
 */
debugRouter.get('/inject-failure', (req: Request, res: Response) => {
  try {
    const type = req.query.type as string;
    const duration = parseInt(req.query.duration as string) || 3000;
    
    logger.warn({ type, duration }, '[DEBUG] Injecting simulated failure');
    
    if (type === 'db') {
      injectDbOutage(duration, 'db');
      res.json({ status: 'INJECTED', type: 'db', duration });
    } else if (type === 'pool') {
      injectDbOutage(duration, 'pool');
      res.json({ status: 'INJECTED', type: 'pool', duration });
    } else if (type === 'redis') {
      injectRedisOutage(duration);
      res.json({ status: 'INJECTED', type: 'redis', duration });
    } else {
      res.status(400).json({ status: 'ERROR', error: 'Invalid failure type. Must be db, pool, or redis.' });
    }
  } catch (err: any) {
    logger.error({ error: err.message }, '[DEBUG ERROR] Failure injection failed');
    res.status(200).json({ status: 'FAILED_SAFE', error: err.message });
  }
});

/**
 * Manually clears all simulated failures.
 */
debugRouter.get('/clear-failure', (_req: Request, res: Response) => {
  try {
    logger.info('[DEBUG] Clearing all injected failures');
    clearDbOutage();
    clearRedisOutage();
    res.json({ status: 'CLEARED' });
  } catch (err: any) {
    logger.error({ error: err.message }, '[DEBUG ERROR] Clearing failures failed');
    res.status(200).json({ status: 'FAILED_SAFE', error: err.message });
  }
});

export default debugRouter;

/**
 * Core API Self-Instrumentation
 *
 * Bootstraps the OpenTelemetry SDK for the Core API service.
 * This MUST be required before any other imports to ensure
 * automatic instrumentation of http, express, and redis is applied.
 *
 * Usage: Add `--require ./dist/instrumentation.js` to node start command,
 *        or import at the very top of src/index.ts.
 */

import { NodeSDK } from '@opentelemetry/sdk-node';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';
import type { Resource } from '@opentelemetry/resources';
import { SEMRESATTRS_SERVICE_NAME, SEMRESATTRS_SERVICE_VERSION } from '@opentelemetry/semantic-conventions';

const OTEL_COLLECTOR_URL = process.env.OTEL_COLLECTOR_URL || 'http://localhost:4318';

const sdk = new NodeSDK({
    resource: new (require('@opentelemetry/resources').Resource)({
        [SEMRESATTRS_SERVICE_NAME]: 'multiagent-core-api',
        [SEMRESATTRS_SERVICE_VERSION]: '1.0.0'
    }),
    traceExporter: new OTLPTraceExporter({
        url: `${OTEL_COLLECTOR_URL}/v1/traces`,
        headers: {}
    }) as any,
    instrumentations: [
        getNodeAutoInstrumentations({
            // Disable noisy file instrumentation; keep http, express, redis
            '@opentelemetry/instrumentation-fs': { enabled: false }
        })
    ]
});

// Graceful startup — if the collector is unavailable, we log a warning
// but do NOT crash the process (critical for local dev without a collector)
try {
    sdk.start();
    console.log(`[Instrumentation] OTel SDK started. Exporting traces to ${OTEL_COLLECTOR_URL}`);
} catch (error) {
    console.warn('[Instrumentation] OTel SDK failed to start. Running without tracing:', error);
}

// Graceful shutdown
process.on('SIGTERM', () => {
    sdk.shutdown()
        .then(() => console.log('[Instrumentation] OTel SDK shut down cleanly'))
        .catch((err: any) => console.error('[Instrumentation] Error shutting down OTel SDK:', err))
        .finally(() => process.exit(0));
});

import express from 'express';
import { logger } from '@packages/observability';

const router = express.Router();

/**
 * Identify the current region and cluster serving the request.
 * Useful for data-plane failover validation.
 */
router.get('/whoami', (req, res) => {
  const region = process.env.REGION || 'us-east-1';
  const clusterId = process.env.CLUSTER_ID || 'cluster-a';
  const sessionId = req.headers['x-session-id'] || 'anonymous';

  res.json({
    region,
    clusterId,
    sessionId,
    timestamp: new Date().toISOString(),
