}

export interface SociotechnicalDrill {
  id: string;
  name: string;
  status: 'INACTIVE' | 'ACTIVE' | 'FAILED' | 'PASSED';
  lastRun: string;
  description: string;
}

export interface StewardshipState {
  epoch: number;
  trustLevel: 'VERIFIED' | 'DEGRADED' | 'UNTRUSTED';
  isSafeMode: boolean;
  escalationTier: 'OPERATOR' | 'SUPERVISOR' | 'HSM_AUTHORITY';
  activeDrill: string;
