export class CacheService {
    /**
     * Generates a deterministic hash for a prompt + context state.
     */
    static generateCacheKey(prompt: string, techStack: any): string {
        const raw = `${prompt}:${JSON.stringify(techStack)}`;
        return `codegen:${crypto.createHash('sha256').update(raw).digest('hex')}`;
    }

    /**
     * Saves code generation results (patches or full files) to Redis cache.
     * Caches expire after 7 days to prevent stale code drift.
     */
    static async setCachedResult(key: string, result: any, ttlSeconds: number = 7 * 24 * 60 * 60): Promise<void> {
        try {
            await redis.set(key, JSON.stringify(result), 'EX', ttlSeconds);
        } catch (error) {
            console.error('[CacheService] Failed to write cache', error);
        }
    }

    /**
     * Retrieves code generation results if they exist.
     */
    static async getCachedResult(key: string): Promise<any | null> {
        try {
            const cached = await redis.get(key);
            if (cached) {
                return JSON.parse(cached);
            }
        } catch (error) {
            console.error('[CacheService] Failed to read cache', error);
        }
        return null;
    }
}

import { redis } from '@packages/utils';
import { logger } from '@packages/observability';

export class CalibrationEngine {
  private static STORAGE_KEY = 'sre:calibration:samples';

  public static async recordSample(confidence: number, outcome: number, hypothesisType?: string, actualType?: string) {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      const samples = samplesJson ? JSON.parse(samplesJson) : [];

      samples.push({
        time: new Date().toISOString(),
        confidence,
        outcome,
        hypothesisType,
        actualType
      });

      // Keep last 500 samples for calibration
      if (samples.length > 500) samples.shift();

      await redis.set(this.STORAGE_KEY, JSON.stringify(samples));
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to record sample in redis');
    }
  }

  public static async calculateHypothesisPrecision(type: string): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 1.0;

      const samples = JSON.parse(samplesJson);
      const relevant = samples.filter((s: any) => s.hypothesisType === type);
      if (relevant.length === 0) return 1.0;

      const correct = relevant.filter((s: any) => s.outcome === 1.0).length;
      return correct / relevant.length;
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to calculate hypothesis precision from redis');
      return 1.0;
    }
  }

  public static async calculateRecall(type: string): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 1.0;

      const samples = JSON.parse(samplesJson);
      // Recall: Predicted_Anomaly / Actual_Anomaly
      const actualAnomalies = samples.filter((s: any) => s.actualType === type);
      if (actualAnomalies.length === 0) return 1.0;

      const correctlyPredicted = actualAnomalies.filter((s: any) => s.hypothesisType === type).length;
      return correctlyPredicted / actualAnomalies.length;
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to calculate recall from redis');
      return 1.0;
    }
  }

  public static async getSupportCount(type: string, isActual: boolean = false): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 0;

      const samples = JSON.parse(samplesJson);
      return samples.filter((s: any) => isActual ? s.actualType === type : s.hypothesisType === type).length;
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to get support count from redis');
      return 0;
    }
  }

  public static async calculateF1(type: string): Promise<number> {
    const precision = await this.calculateHypothesisPrecision(type);
    const recall = await this.calculateRecall(type);
    if (precision + recall === 0) return 0;
    return 2 * (precision * recall) / (precision + recall);
  }

  /**
   * Calculate Brier Score: Mean Squared Error of predictions
   * Ranges from 0.0 (Perfect) to 1.0 (Total Failure)
   */
  public static async calculateBrierScore(): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 0;

      const samples = JSON.parse(samplesJson);
      if (samples.length === 0) return 0;

      const squaredErrors = samples.map((s: any) => Math.pow(s.confidence - s.outcome, 2));
      const meanSquaredError = squaredErrors.reduce((a: number, b: number) => a + b, 0) / samples.length;

      return meanSquaredError;
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to calculate Brier score from redis');
      return 0;
    }
  }

  public static async getAnomalyArrivalRate(): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 0;

      const samples = JSON.parse(samplesJson);
      const anomalies = samples.filter((s: any) => s.actualType && s.actualType !== 'NOMINAL');
      if (anomalies.length === 0) return 0;

      const first = new Date(samples[0].time).getTime();
      const last = new Date(samples[samples.length - 1].time).getTime();
      const durationHours = (last - first) / (3600 * 1000);

      return anomalies.length / (durationHours || 1);
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to get anomaly arrival rate from redis');
      return 0;
    }
  }

  public static async isStatisticallySignificant(type: string): Promise<boolean> {
    const support = await this.getSupportCount(type, true);
    const rate = await this.getAnomalyArrivalRate();
    
    // Significance requires at least 30 samples OR enough to cover the expected rate
    const minSupport = Math.max(30, rate * 6); // 6-hour coverage equivalent
    return support >= minSupport;
  }
}

import * as Y from 'yjs';
import { db as prisma } from '@packages/db';
import logger from '@packages/utils';

/**
 * CollaborationPersistence
 * 
 * Production-ready Yjs persistence using Postgres.
 * Handles loading initial document state and persisting incremental updates.
 */
export class CollaborationPersistence {
    /**
     * Binds a Yjs document to Postgres persistence.
     * Loads the initial state from DB if it exists.
     */
    async bindState(docName: string, ydoc: Y.Doc) {
        try {
            const doc = await prisma.collaborativeDoc.findUnique({
                where: { name: docName }
            });

            if (doc && doc.updates) {
                Y.applyUpdate(ydoc, doc.updates);
                logger.debug({ docName }, '[YJS:Persistence] Initial state loaded from Postgres');
            } else {
                logger.debug({ docName }, '[YJS:Persistence] No existing state found, starting fresh');
            }

            // Listen for updates and persist them
            ydoc.on('update', async (_update: Uint8Array) => {
                await this.storeUpdate(docName, ydoc);
            });
        } catch (err) {
            logger.error({ docName, err }, '[YJS:Persistence] Failed to bind document state');
        }
    }

    public async load(docName: string): Promise<Uint8Array | null> {
        const doc = await prisma.collaborativeDoc.findUnique({
            where: { name: docName }
        });
        return doc?.updates ? new Uint8Array(doc.updates) : null;
    }

    public async save(docName: string, update: Uint8Array): Promise<void> {
        await prisma.collaborativeDoc.upsert({
            where: { name: docName },
            update: { updates: Buffer.from(update) },
            create: { 
                name: docName, 
                updates: Buffer.from(update) 
            }
        });
    }

    /**
     * Merges current document state and persists to Postgres.
     */
    private async storeUpdate(docName: string, ydoc: Y.Doc) {
        try {
            const state = Y.encodeStateAsUpdate(ydoc);
            await this.save(docName, state);
        } catch (err) {
            logger.error({ docName, err }, '[YJS:Persistence] Failed to store document update');
        }
    }
}

export const collaborationPersistence = new CollaborationPersistence();

import { logger } from '@packages/observability';

export interface DecisionInput {
  anomalyScore: number;
  burnRate: number;
}

export type SreDecision =
  | 'NO_ACTION'
  | 'OBSERVE'
  | 'ALERT'
  | 'ACT';

/**
 * DecisionEngine: Converts signals (Anomaly Score) and impact (Burn Rate)
 * into deterministic operational decisions.
 */
export class DecisionEngine {
  /**
   * Decide the next action based on signal strength and SLO impact.
   */
  public decide(input: DecisionInput): SreDecision {
    // 1. Critical Impact + Confirmed Anomaly -> ACT
    if (input.burnRate > 5 && input.anomalyScore > 0.7) {
      return 'ACT';
    }

    // 2. High Burn Rate -> ALERT (Even if anomaly is weak, impact is high)
    if (input.burnRate > 2) {
      return 'ALERT';
    }

    // 3. Signal Breach -> OBSERVE (Signal is high, but budget impact is low)
    if (input.anomalyScore > 0.7) {
      return 'OBSERVE';
    }

    return 'NO_ACTION';
  }
}

export const decisionEngine = new DecisionEngine();

