    try {
      await db.ztanIdentity.update({
        where: { nodeId },
        data: { 
          publicKey: newPublicKey,
          status: 'ACTIVE'
        }
      });
      logger.info({ nodeId }, '[IDENTITY] Node public key rotated in persistent store');
    } catch (err: any) {
      logger.error({ nodeId, err: err.message }, '[IDENTITY] Key rotation failed');
