import type { NodeState, Edge, CausalGraph } from './causal-graph.types.js';
import { logger } from '@packages/observability';
import { topologyManager } from './causal-topology.js';

export class ProbabilisticCausalEngine {
  constructor(private graph: CausalGraph) {}

  /**
   * Computes the probability that each node is the root cause given the observed anomalies.
   * Based on Bayesian inference: P(RootCause | Observed)
   */
  public computeRootProbabilities(states: NodeState[]): Record<string, number> {
    const scores: Record<string, number> = {};

    for (const node of this.graph.nodes) {
      const prior = this.getPrior(node, states);
      const likelihood = this.computeLikelihood(node, states);

      scores[node] = prior * likelihood;
    }

    return this.normalize(scores);
  }

  private getPrior(node: string, states: NodeState[]): number {
    const state = states.find((s: NodeState) => s.nodeId === node);
    if (!state || state.anomalyScore < 0.2) return 0.01;

    // Penalty if parents are also anomalous (likely an effect, not root)
    let parentPenalty = 1.0;
    const parents = this.graph.edges.filter((e: Edge) => e.to === node).map((e: Edge) => e.from);
    
    for (const parentId of parents) {
      const parentState = states.find((s: NodeState) => s.nodeId === parentId);
      if (parentState && parentState.anomalyScore > 0.4) {
        parentPenalty *= 0.3; // Significant penalty for each anomalous parent
      }
    }

    return state.anomalyScore * parentPenalty;
  }

  private computeLikelihood(node: string, states: NodeState[]): number {
    let likelihood = 1.0;

    // Likelihood: How well does this node being the cause explain the downstream anomalies?
    for (const edge of this.graph.edges) {
      if (edge.from === node) {
        const downstream = states.find((s: NodeState) => s.nodeId === edge.to);

        if (downstream && downstream.anomalyScore > 0.2) {
          // If node is cause, downstream SHOULD be anomalous (scaled by edge weight)
          likelihood *= (edge.weight * downstream.anomalyScore);
        } else {
          // If node is cause but downstream is healthy, it's less likely (but possible due to edge weight)
          likelihood *= (1.0 - edge.weight);
        }
      }
    }

    return likelihood;
  }

  private normalize(scores: Record<string, number>): Record<string, number> {
    const total = Object.values(scores).reduce((a: number, b: number) => a + b, 0);
    
    if (total === 0) {
      // If no signal, return uniform distribution or zeros
      const uniform: Record<string, number> = {};
      this.graph.nodes.forEach((n: string) => uniform[n] = 0);
      return uniform;
    }

    const normalized: Record<string, number> = {};
    Object.keys(scores).forEach((k: string) => {
      normalized[k] = scores[k] / total;
    });

    return normalized;
  }
}

/**
 * RootSelector: Selects the most likely root causes based on a probability threshold.
 */
export class RootSelector {
  public static select(probabilities: Record<string, number>, threshold = 0.2): [string, number][] {
    return Object.entries(probabilities)
      .filter(([_, p]: [string, number]) => p > threshold)
      .sort((a: [string, number], b: [string, number]) => b[1] - a[1]);
  }
}

/**
 * TemporalConsistencyFilter: Validates candidates against temporal precedence (Cause must happen before Effect).
 */
export class TemporalConsistencyFilter {
  public static validate(candidate: string, states: any[], edges: Edge[]): boolean {
    const nodeState = states.find((s: any) => s.nodeId === candidate);
    if (!nodeState) return false;

    const nodeTime = nodeState.timestamp;

    for (const edge of edges) {
      if (edge.from === candidate) {
        const downstream = states.find((s: any) => s.nodeId === edge.to);
        // If downstream alert exists and it happened BEFORE the candidate, it violates causality
        if (downstream && downstream.anomalyScore > 0.4 && downstream.timestamp < nodeTime - 50) { // 50ms buffer for jitter
          return false;
        }
      }
    }

    return true;
  }
}

import { redis } from '@packages/utils';
import { logger } from '@packages/observability';

export interface RLState {
  anomalyScore: number;
  burnRate: number;
  latencyP95: number;
  errorRate: number;
  reliabilityScore: number;
}

export class QLearningAgent {
  private static Q_TABLE_KEY = 'sre:q-table';
  private qTable: Record<string, Record<string, number>> = {};
  
  private learningRate = 0.1;
  private discountFactor = 0.9;
  private epsilon = 0.1; // Exploration rate

  constructor() {
    this.load();
  }

  private async load() {
    try {
      const saved = await redis.get(QLearningAgent.Q_TABLE_KEY);
      if (saved) {
        this.qTable = JSON.parse(saved);
      }
    } catch (err: any) {
      logger.warn({ err }, '[RL] Failed to load Q-Table from Redis due to connection/command error');
    }
  }

  private async save() {
    try {
      await redis.set(QLearningAgent.Q_TABLE_KEY, JSON.stringify(this.qTable));
    } catch (err: any) {
      logger.warn({ err }, '[RL] Failed to save Q-Table to Redis due to connection/command error');
    }
  }



  /**
   * Discretizes the continuous state into a string key for the Q-table.
   */
  private getStateKey(state: RLState): string {
    const anomalyIdx = Math.floor(state.anomalyScore * 5); // 0-4
    const burnIdx = Math.floor(Math.min(state.burnRate, 10) / 2); // 0-5
    const latencyIdx = Math.floor(Math.min(state.latencyP95, 2000) / 400); // 0-5
    const reliabilityIdx = Math.floor(state.reliabilityScore * 4); // 0-3 (Low, Med, High, Critical)
    
    return `a${anomalyIdx}:b${burnIdx}:l${latencyIdx}:r${reliabilityIdx}`;
  }

  public chooseAction(state: RLState, actions: string[]): string {
    const stateKey = this.getStateKey(state);

    // Epsilon-greedy exploration
    if (Math.random() < this.epsilon) {
      return actions[Math.floor(Math.random() * actions.length)];
    }

    const stateActions = this.qTable[stateKey] || {};
    
    // Find action with highest Q-value
    let bestAction = actions[0];
    let maxQ = -Infinity;

    for (const action of actions) {
      const q = stateActions[action] || 0;
      if (q > maxQ) {
        maxQ = q;
        bestAction = action;
      }
    }

    return bestAction;
  }

  public async update(
    state: RLState, 
    action: string, 
    reward: number, 
    nextState: RLState
  ) {
    const stateKey = this.getStateKey(state);
    const nextStateKey = this.getStateKey(nextState);

    if (!this.qTable[stateKey]) this.qTable[stateKey] = {};
    const currentQ = this.qTable[stateKey][action] || 0;

    // Find max Q for next state
    const nextStateActions = this.qTable[nextStateKey] || {};
    const maxNextQ = Object.values(nextStateActions).length > 0 
      ? Math.max(...Object.values(nextStateActions)) 
      : 0;

    // Q-Learning update rule
    const updatedQ = currentQ + this.learningRate * (reward + this.discountFactor * maxNextQ - currentQ);
    
    this.qTable[stateKey][action] = updatedQ;
    
    // Save periodically (or on every update for small scale)
    await this.save();
  }

  /**
   * Reward function: Optimizes for SLO compliance while penalizing instability and cost.
   */
  public computeReward(params: {
    errorRate: number;
    latency: number;
    actionPerformed: boolean;
    improvement: number;
    humanFeedback?: 'APPROVED' | 'REJECTED';
    roiAccuracy?: number;
  }): number {
    let reward = 0;

    // 1. SLO Penalty (Strongest signal)
    reward -= params.errorRate * 10;
    
    // 2. Latency Penalty
    reward -= (params.latency / 1000) * 2;

    // 3. Action Penalty (Avoid unnecessary interventions)
    if (params.actionPerformed) {
      reward -= 0.5;
      
      // 4. Improvement Bonus
      if (params.improvement > 0) {
        reward += params.improvement * 5;
      } else {
        reward -= 2.0; // Failed intervention penalty
      }
    } else {
      reward += 0.2; // Reward for stability when nominal
    }

    // 5. Human Feedback (Strongest policy shaper)
    if (params.humanFeedback === 'APPROVED') {
      reward += 10.0;
    } else if (params.humanFeedback === 'REJECTED') {
      reward -= 20.0;
    }

    // 6. ROI Accuracy (Policy Calibration)
    if (params.roiAccuracy !== undefined) {
      if (params.roiAccuracy < 0.5) {
        reward -= 20.0; // Critical penalty for uncalibrated business logic
      } else {
        reward += params.roiAccuracy * 10;
      }
    }

    return reward;
  }
}

export const qLearningAgent = new QLearningAgent();

import axios from 'axios';
import { logger } from '@packages/observability';

export class EmbeddingsEngine {
    private static readonly OPENAI_API_URL = 'https://api.openai.com/v1/embeddings';
    private static readonly MODEL = 'text-embedding-3-small';

    /**
     * Generates vector embeddings for a given text string.
     */
    static async generate(text: string): Promise<number[] | null> {
        const apiKey = process.env.OPEN_AI_KEY || process.env.OPENAI_API_KEY;

        if (!apiKey) {
            logger.warn('[EmbeddingsEngine] OPENAI_API_KEY is missing. Skipping vector generation.');
            return null;
        }

        try {
            const response = await axios.post(
                this.OPENAI_API_URL,
                {
                    input: text,
                    model: this.MODEL,
                    encoding_format: 'float',
                },
                {
                    headers: {
                        'Authorization': `Bearer ${apiKey}`,
                        'Content-Type': 'application/json',
                    },
                }
            );

            return response.data.data[0].embedding;
        } catch (error: any) {
            const errorMsg = error.response?.data?.error?.message || error.message;
            logger.error({ error: errorMsg }, '[EmbeddingsEngine] Failed to generate embedding');
            return null;
        }
    }

    /**
     * Generates embeddings for multiple chunks in a single batch.
     */
    static async generateBatch(texts: string[]): Promise<number[][] | null> {
        const apiKey = process.env.OPEN_AI_KEY || process.env.OPENAI_API_KEY;
        if (!apiKey || texts.length === 0) return null;

        try {
            const response = await axios.post(
                this.OPENAI_API_URL,
                {
                    input: texts,
                    model: this.MODEL,
                    encoding_format: 'float',
                },
                {
                    headers: {
                        'Authorization': `Bearer ${apiKey}`,
                        'Content-Type': 'application/json',
                    },
                }
            );

            return response.data.data.map((item: any) => item.embedding);
        } catch (error: any) {
            logger.error({ error: error.message }, '[EmbeddingsEngine] Batch generation failed');
            return null;
        }
    }
}

