                orderBy: { updatedAt: 'desc' }
            });
            return data as any as Project[];
        } catch (error) {
            console.error('[ProjectService] Error fetching projects:', error);
            return null;
        }
    },

    async getPublicProjects(limit = 20) {
        try {
            const data = await db.project.findMany({
                where: { status: 'active' }, // Assuming 'active' projects can be public
                orderBy: { updatedAt: 'desc' },
                take: limit
            });
            return data as any as Project[];
        } catch (error) {
            console.error('[ProjectService] Error fetching public projects:', error);
            return null;
        }
    },

    async getProject(id: string, tenantId: string) {
        try {
            const data = await db.project.findFirst({
                where: { id, tenantId }
            });
            return data as any as Project;
        } catch (error) {
            console.error('[ProjectService] Error fetching project:', error);
            return null;
        }
    },

    async createProject(name: string, tenantId: string, description?: string, type?: string) {
        try {
            const data = await db.project.create({
                data: {
                    tenantId,
                    name,
                    description,
                    status: 'draft'
                }
            });
            return { data: data as any as Project, error: null };
        } catch (error) {
            console.error('[ProjectService] Error creating project:', error);
            return { data: null, error };
        }
    },

    async getProjectFiles(projectId: string, tenantId: string) {
        try {
            // Scope lookup: Use parent relation to enforce tenancy in a single query
            const data = await db.projectFile.findMany({
                where: { 
                    projectId,
                    project: { tenantId }
                },
                orderBy: { path: 'asc' }
            });
            return data as any as ProjectFile[];
        } catch (error) {
            console.error('[ProjectService] Error fetching project files:', error);
            return null;
        }
    },

    async updateFile(id: string, content: string, tenantId: string) {
        try {
            // Verify that the file belongs to a project owned by this tenant
            const file = await db.projectFile.findFirst({
                where: {
                    id,
                    project: { tenantId }
                }
            });
            if (!file) {
                throw new Error('Unauthorized or file not found');
            }

            const data = await db.projectFile.update({
                where: { id },
                data: { content, updatedAt: new Date() }
            });
            return data as any as ProjectFile;
        } catch (error) {
            console.error('[ProjectService] Error updating file:', error);
            throw error;
        }
    },

    async updateProject(id: string, tenantId: string, project: Partial<Project>) {
        try {
            const data = await db.project.updateMany({
                where: { id, tenantId },
                data: {
                    ...project,
                    updatedAt: new Date()
                } as any
            });
            if (data.count === 0) throw new Error('Project not found or tenant mismatch');
            return { data: project as any as Project, error: null };
        } catch (error) {
            console.error('[ProjectService] Error updating project:', error);
            return { data: null, error };
        }
    },

    async deleteProject(id: string, tenantId: string) {
        try {
            const result = await db.project.deleteMany({
                where: { id, tenantId }
            });
            return result.count > 0;
        } catch (error) {
            console.error('[ProjectService] Error deleting project:', error);
            return false;
        }
    },

    async verifyProjectOwnership(projectId: string, tenantId: string) {
        try {
            const data = await db.project.findUnique({
                where: { id: projectId },
                select: { tenantId: true }
            });
            return data?.tenantId === tenantId;
        } catch (error) {
            return false;
        }
    },

    async saveProjectFiles(projectId: string, files: { path: string, content: string, language?: string }[], tenantId: string) {
        try {
            // Verify project ownership first
            const isOwner = await this.verifyProjectOwnership(projectId, tenantId);
            if (!isOwner) {
                throw new Error('Unauthorized or project not found');
            }

            // 1. Deduplicate files by path
            const uniqueFilesMap = new Map<string, any>();
            files.forEach(f => {
                if (f.path) {
                    let normPath = f.path.replace(/\\/g, '/');
                    if (!normPath.startsWith('/')) normPath = '/' + normPath;
                    uniqueFilesMap.set(normPath, { ...f, path: normPath });
                }
            });
            const uniqueFiles = Array.from(uniqueFilesMap.values());

            // 2. Transactional Upsert: Delete existing, Insert new
            // Verified: Enforce tenancy on the primary delete operation
            await db.$transaction([
                db.projectFile.deleteMany({ 
                    where: { 
                        projectId,
                        project: { tenantId } // Safely enforce parent relation tenancy
                    } 
                }),
                db.projectFile.createMany({
                    data: uniqueFiles.map(f => ({
                        projectId,
                        path: f.path,
                        content: f.content,
                        language: f.language || f.path.split('.').pop()
                    }))
                })
            ]);

            return true;
        } catch (error) {
            console.error('[ProjectService] Error saving project files:', error);
            throw error;
        }
    }
};

import { logger } from '@packages/observability';
import { retryCountTotal } from '@packages/utils';

export class RetryManager {
    private maxRetries: number;
    private baseDelayMs: number;

    constructor(maxRetries: number = 2, baseDelayMs: number = 2000) {
        this.maxRetries = maxRetries;
        this.baseDelayMs = baseDelayMs;
    }

    async executeWithRetry<T>(
        operation: () => Promise<T>,
        agentName: string,
        _context: any
    ): Promise<T> {
        let lastError: unknown;
        const timeoutMs = 90000;

        for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
            try {
                if (attempt > 1) {
                    const delay = this.baseDelayMs * Math.pow(2, (attempt - 2));
                    logger.warn({ agentName, attempt, delay }, 'Retrying agent execution...');
                    retryCountTotal.inc({ agent_name: agentName });
                    await new Promise(resolve => setTimeout(resolve, delay));
                }

                return await Promise.race([
                    operation(),
                    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(`Agent execution timed out after ${timeoutMs}ms`)), timeoutMs))
                ]);
            } catch (error: any) {
                lastError = error;
                const status = error?.status;
                const isRateLimit = status === 429 || error?.message?.includes('rate_limit_exceeded');

                if (isRateLimit) {
                    const delay = this.baseDelayMs * Math.pow(2, (attempt - 1)); // Moderated backoff for rate limits
                    logger.warn({ agentName, attempt, delay }, 'Rate limit exceeded. Backing off...');
                    await new Promise(resolve => setTimeout(resolve, delay));
                    continue; // Immediately retry after backoff
                }

                const errorMessage = error instanceof Error ? error.message : String(error);
                logger.error({
                    agentName,
                    attempt,
                    error: errorMessage
                }, 'Agent execution failed');

                if (error && typeof error === 'object' && 'isFatal' in error && (error as any).isFatal) {
                    logger.error({ agentName }, 'Fatal error detected. Aborting retries.');
                    break;
                }

                if (attempt === this.maxRetries) break;
            }
        }

        const finalErrorMessage = lastError instanceof Error ? lastError.message : String(lastError);
        throw new Error(`Max retries reached for ${agentName}: ${finalErrorMessage}`);
    }
}

/**
 * AI Safety Service: Prompt Injection Defense & Output Filtering.
 */
export const safetyService = {
  /**
   * Sanitizes user input to prevent prompt injection and unauthorized command execution.
   */
  async sanitizePrompt(prompt: string): Promise<string> {
    const blockedKeywords = [
      'ignore previous instructions',
      'reveal secrets',
      'system prompt',
      'process.env',
      'delete everything',
      'rm -rf /',
    ];

    const lowPrompt = prompt.toLowerCase();
    
    for (const keyword of blockedKeywords) {
      if (lowPrompt.includes(keyword)) {
        throw new Error(`Safety Alert: Unsafe content detected ("${keyword}")`);
      }
    }

    return prompt;
  },

  /**
   * Filters agent outputs to prevent sensitive data leaks.
   */
  async filterOutput(output: string): Promise<string> {
    // Basic regex for potential API keys or secrets
    const secretRegex = /(sk-[a-zA-Z0-9]{32}|AKIA[0-9A-Z]{16})/g;
    
    if (secretRegex.test(output)) {
      console.warn('[Safety] Blocked potential secret leak in LLM response.');
      return output.replace(secretRegex, '[REDACTED]');
    }

    return output;
  },

  /**
   * Calculates a risk score for an agentic operation.
   */
  calculateRiskScore(action: string, context: any): number {
    let score = 0;
    
    if (action.includes('delete') || action.includes('filesystem')) score += 0.5;
    if (action.includes('network') || action.includes('shell')) score += 0.4;
    
    return Math.min(score, 1.0);
  }
};

