import { Server, Socket } from 'socket.io';
import { logger } from '@packages/observability';
import { sreEngine } from './sre-engine.js';
import type { SRETuningParams } from '@packages/contracts';
import { chaosOrchestrator } from './chaos-orchestrator.js';
import type { ChaosScenario } from './chaos-orchestrator.js';
import { validationEngine } from './validation-engine.js';
import { soakTester } from './soak-tester.js';
import { SreAnalyticsService } from './operational-control/sre-analytics.js';

export class SreStreamingService {
    private io: Server;
    private lastBroadcastState: any = null;
    private lastFullBroadcastTime: number = 0;

    constructor(io: Server) {
        this.io = io;
        this.setupSubscriptions();
        this.setupEventListeners();
        this.startTelemetryBroadcast();
    }

    private setupEventListeners() {
        // Immediate broadcast on state transition (captures jitter)
        sreEngine.on('stateChange', async (state: any) => {
            logger.debug('[SRE] State transition detected - broadcasting immediately');
            await this.broadcast(state);
        });

        // Analytics stream
        SreAnalyticsService.setOnEventListener((event: any) => {
            this.io.to('sre:analytics').emit('sre:analytics:event', event);
        });
    }

    private setupSubscriptions() {
        this.io.on('connection', (socket: Socket) => {
            // Subscribe to SRE Telemetry
            socket.on('sre:subscribe', () => {
                logger.info({ socketId: socket.id }, '[SRE] Client subscribed to SRE telemetry');
                socket.join('sre:telemetry');
                
                // Send current state immediately
                sreEngine.getCurrentStateAsync().then((state: any) => {
                    socket.emit('sre:update', state);
                });
            });

            // Subscribe to Analytics
            socket.on('sre:analytics:subscribe', async () => {
                logger.info({ socketId: socket.id }, '[SRE] Client subscribed to SRE analytics');
                socket.join('sre:analytics');
                const events = await SreAnalyticsService.getRecentEvents(50);
                socket.emit('sre:analytics:init', events);
            });

            // Update Tuning Parameters
            socket.on('sre:tune', async (params: Partial<SRETuningParams>) => {
                logger.warn({ socketId: socket.id, params }, '[SRE] Tuning update requested');
                try {
                    await sreEngine.updateTuning(params);
                    // Broadcast update immediately after tuning
                    const state = await sreEngine.getCurrentStateAsync();
                    await this.broadcast(state);
                } catch (err: any) {
                    logger.error({ err, socketId: socket.id }, '[SRE] Tuning rejected due to safety violation');
                    socket.emit('sre:error', { message: err.message });
                }
            });

            // Mock Signal Injection (for field validation testing)
            socket.on('sre:inject_signal', (signal: any) => {
                logger.info({ socketId: socket.id, signal }, '[SRE] Manual signal injected');
                sreEngine.registerObserverSignal(signal);
            });

            // Network Disorder Feedback Loop
            socket.on('sre:network_disorder', (data: { sequenceId: number, lastSequenceId: number, totalDisordered: number }) => {
                logger.warn({ data }, '[SRE] Client reported network disorder / sequence inversion');
                sreEngine.reportNetworkDisorder(data.totalDisordered);
            });

            // Production Validation Hooks (Chaos Engineering)
            socket.on('sre:chaos_inject', (payload: { scenario: ChaosScenario, nodeId?: string }) => {
                validationEngine.onChaosStart();
                const scenario = typeof payload === 'string' ? payload : payload.scenario;
                const nodeId = (payload as any).nodeId || 'api-service';
                chaosOrchestrator.inject(scenario as ChaosScenario, nodeId);
                this.broadcastImmediate();
            });

            socket.on('sre:chaos_clear', () => {
                // We don't know if it was detected until we check the current state
                // But for simplicity, we'll assume the engine handles it.
                // Better: Check if any anomalies were detected during chaos.
                chaosOrchestrator.clear();
                this.broadcastImmediate();
            });

            socket.on('sre:validation_reset', () => {
                validationEngine.reset();
                this.broadcastImmediate();
            });

            socket.on('sre:soak_start', () => {
                soakTester.start();
                this.broadcastImmediate();
            });

            socket.on('sre:soak_stop', () => {
                soakTester.stop();
                this.broadcastImmediate();
            });

            socket.on('sre:approve', async (data: { requestId: string, rationale: string }) => {
                logger.info({ requestId: data.requestId }, '[SRE] Operator APPROVED action');
                await sreEngine.handleApproval(data.requestId, 'APPROVED', data.rationale);
                this.broadcastImmediate();
            });

            socket.on('sre:reject', async (data: { requestId: string, rationale: string }) => {
                logger.info({ requestId: data.requestId }, '[SRE] Operator REJECTED action');
                await sreEngine.handleApproval(data.requestId, 'REJECTED', data.rationale);
                this.broadcastImmediate();
            });
        });
    }

    private startTelemetryBroadcast() {
        // Broadcast SRE state every 2 seconds to all subscribers
        setInterval(async () => {
            const state = await sreEngine.getCurrentStateAsync();
            if (this.io.sockets.adapter.rooms.has('sre:telemetry')) {
                logger.debug('[SRE STREAM] Broadcasting state to subscribers');
            }
            await this.broadcast(state);
        }, 2000);
    }

    private async broadcast(state: any) {
        const now = Date.now();
        const needsFullUpdate = now - this.lastFullBroadcastTime > 5000 || this.hasSignificantChange(state);

        const payload = needsFullUpdate ? state : this.computeDelta(state);

        this.io.to('sre:telemetry').emit('sre:update', payload);

        if (needsFullUpdate) {
            this.lastFullBroadcastTime = now;
            this.lastBroadcastState = JSON.parse(JSON.stringify(state));
        }
    }

    private hasSignificantChange(current: any): boolean {
        if (!this.lastBroadcastState) return true;
        if (current.operationalControl.mode !== this.lastBroadcastState.operationalControl.mode) return true;
        if (current.operationalControl.reasonType !== this.lastBroadcastState.operationalControl.reasonType) return true;
        
        const consensusDelta = Math.abs(current.perception.consensus - this.lastBroadcastState.perception.consensus);
        if (consensusDelta > 0.05) return true;

        const stabilityDelta = Math.abs((current.stability?.score || 0) - (this.lastBroadcastState.stability?.score || 0));
        if (stabilityDelta > 0.05) return true;

        return false;
    }

    private computeDelta(current: any): any {
        return {
            sequenceId: current.sequenceId,
            timestamp: current.timestamp,
            isDelta: true,
            operationalControl: {
                mode: current.operationalControl.mode,
                reasonType: current.operationalControl.reasonType,
                reason: current.operationalControl.reason,
                reasoningDecomposition: current.operationalControl.reasoningDecomposition,
                approvalRequestId: current.operationalControl.approvalRequestId
            },
            stability: current.stability,
            elite: (current as any).elite,
            perception: {
                consensus: current.perception.consensus,
                signalIntegrityState: current.perception.signalIntegrityState,
                anomalyHypothesis: current.perception.anomalyHypothesis,
                brierScore: current.perception.brierScore,
                wassersteinDistance: current.perception.wassersteinDistance
            },
            validation: {
                ...current.validation,
                history: validationEngine.getHistory()
            },
            audit: current.audit,
            topology: current.topology,
            soak: soakTester.getStatus()
        };
    }

    private async broadcastImmediate() {
        const state = await sreEngine.getCurrentState();
        await this.broadcast(state);
    }
}

import { redis } from '@packages/utils';
import { logger } from '@packages/observability';

export class StabilityEngine {
  private static STORAGE_KEY = 'sre:stability:history';
  private static MAX_HISTORY = 50;

  /**
   * Record the identified root cause to track oscillations over time.
   */
  public static async recordRootCause(root: string) {
    try {
      const historyJson = await redis.get(this.STORAGE_KEY);
      const history: string[] = historyJson ? JSON.parse(historyJson) : [];

      history.push(root);
      if (history.length > this.MAX_HISTORY) history.shift();

      await redis.set(this.STORAGE_KEY, JSON.stringify(history));
    } catch (err: any) {
      logger.warn({ err }, '[STABILITY] Failed to record root cause to redis due to connection/command error');
    }
  }

  /**
   * Calculate stability score based on decaying flip rate (EWMA).
   * Recent flips have a higher impact on reliability degradation.
   */
  public static async calculateStabilityScore(): Promise<number> {
    try {
      const historyJson = await redis.get(this.STORAGE_KEY);
      if (!historyJson) return 1.0;

      const history: string[] = JSON.parse(historyJson);
      if (history.length < 3) return 1.0;

      const ALPHA = 0.4; // Smoothing factor (higher = more responsive to recent flips)
      let ewmaFlipRate = 0;

      for (let i = 1; i < history.length; i++) {
        const flip = history[i] !== history[i - 1] ? 1 : 0;
        ewmaFlipRate = (ALPHA * flip) + ((1 - ALPHA) * ewmaFlipRate);
      }

      const stability = Math.max(0.0, 1.0 - ewmaFlipRate);

      logger.debug({ 
        ewmaFlipRate: ewmaFlipRate.toFixed(4), 
        historyLength: history.length, 
        stability: stability.toFixed(4) 
      }, '[STABILITY] EWMA Score calculated');
      
      return stability;
    } catch (err: any) {
      logger.warn({ err }, '[STABILITY] Failed to calculate stability score from redis due to connection/command error');
      return 1.0;
    }
  }

  public static async reset() {
    try {
      await redis.del(this.STORAGE_KEY);
    } catch (err: any) {
      logger.warn({ err }, '[STABILITY] Failed to reset stability history in redis due to connection/command error');
    }
  }
}

import { Redis } from 'ioredis';
import { db } from '@packages/db';
import { logger } from '@packages/observability';

const REDIS_URL = process.env.REDIS_URL || 'redis://localhost:6379';

interface BuildEvent {
    executionId: string;
    type: 'progress' | 'thought' | 'agent' | 'complete' | 'error';
    projectId: string; // Scoped to Project (Mission)
    payload: any;
}

export class StateReconciler {
    private subscriber: Redis;

    constructor() {
        this.subscriber = new Redis(REDIS_URL);
    }

    public async connect() {
        this.subscriber.subscribe('build-events', (err) => {
            if (err) {
                logger.error({ err }, '[StateReconciler] Failed to subscribe to build-events');
                return;
            }
            logger.info('[StateReconciler] Subscribed to Redis build-events for persistence sync');
        });

        this.subscriber.on('message', async (channel, message) => {
            if (channel === 'build-events') {
                await this.handleEvent(message);
            }
        });
    }

    private async handleEvent(message: string) {
        try {
            const event: BuildEvent = JSON.parse(message);
            const { executionId, type, projectId, payload } = event;

            if (!projectId) return;

            switch (type) {
                case 'complete':
                    await this.updateMissionStatus(projectId, 'completed');
                    await this.saveBuildMetrics(projectId, payload);
                    break;
                case 'error':
                    await this.updateMissionStatus(projectId, 'failed', payload?.error);
                    break;
                case 'progress':
                    // Optional: Update last active timestamp
                    break;
            }
        } catch (err) {
            logger.error({ err }, '[StateReconciler] Event processing failure');
        }
    }

    private async saveBuildMetrics(projectId: string, payload: any) {
        try {
            await db.buildMetric.create({
                data: {
                    projectId,
                    tokensUsed: Number(payload.tokensUsed || 0),
                    durationMs: Number(payload.durationMs || 0),
                    costUsd: Number(payload.costUsd || 0),
                    status: 'completed'
                }
            });
            logger.info({ projectId }, '[StateReconciler] Persisted build metrics');
        } catch (err) {
            logger.error({ err, projectId }, '[StateReconciler] Failed to persist metrics');
        }
    }

    private async updateMissionStatus(id: string, status: 'completed' | 'failed', error?: string) {
        try {
            // Note: Project model in schema.prisma corresponds to a "Mission" in this context
            await db.project.update({
                where: { id },
                data: { 
                    status,
                    updatedAt: new Date(),
                    // If we had a detailed log field, we'd append here
                }
            });
            logger.info({ id, status }, '[StateReconciler] Reconciled mission state in DB');
        } catch (err) {
            logger.error({ err, id }, '[StateReconciler] DB Sync failure');
        }
    }
}

export const stateReconciler = new StateReconciler();

